import pytest
import json
from unittest.mock import Mock, patch, MagicMock
from typing import Dict, List, Set


class CredentialRenameTestHarness:
    """Test harness for PMA credential rename from 'Registered Outcomes Advisor'"""

    OLD_CREDENTIAL_NAME = "Registered Outcomes Advisor"
    NEW_CREDENTIAL_NAME = "Prediction Markets Advisor"
    NEW_CREDENTIAL_SHORT = "PMA"

    def __init__(self):
        self.database = Mock()
        self.site_content = {}
        self.application_flows = {}
        self.exam_pages = {}
        self.waiver_templates = {}
        self.config = {}

    def verify_no_old_references(self, content: str, context: str) -> tuple[bool, List[str]]:
        """Verify old credential name not present (case-insensitive)"""
        import re
        # Match old name with word boundaries
        pattern = re.compile(r'\b' + re.escape(self.OLD_CREDENTIAL_NAME) + r'\b', re.IGNORECASE)
        matches = pattern.findall(content)
        if matches:
            return False, [f"{context}: Found '{m}' at position {pos}" for m, pos in [(m, content.find(m)) for m in matches]]
        return True, []

    def verify_new_references(self, content: str, context: str) -> tuple[bool, List[str]]:
        """Verify new credential name appears where expected"""
        errors = []
        has_pma = self.NEW_CREDENTIAL_NAME in content
        if not has_pma and context not in ["old_documentation", "deprecation_notice"]:
            errors.append(f"{context}: Missing '{self.NEW_CREDENTIAL_NAME}'")
        return len(errors) == 0, errors

    def verify_waiver_language(self, waiver: str) -> tuple[bool, List[str]]:
        """Verify waiver contains proper credential language for CFA/CFP/FRM"""
        errors = []
        required_fields = [
            "credential_name",
            "regulatory_statement",
            "scope_of_authority",
            "limitation_notice"
        ]
        for field in required_fields:
            if field not in waiver:
                errors.append(f"Waiver missing required field: {field}")

        # Verify no old credential name in waiver
        is_clean, old_refs = self.verify_no_old_references(waiver, "waiver_language")
        if not is_clean:
            errors.extend(old_refs)

        # Verify new credential name present
        if self.NEW_CREDENTIAL_NAME not in waiver:
            errors.append(f"Waiver missing new credential name: {self.NEW_CREDENTIAL_NAME}")

        return len(errors) == 0, errors

    def verify_exam_pages(self, exam_page: Dict) -> tuple[bool, List[str]]:
        """Verify exam pages reference correct credential"""
        errors = []
        required_keys = ["title", "description", "eligibility", "content"]

        for key in required_keys:
            if key not in exam_page:
                errors.append(f"Exam page missing: {key}")
                continue

            is_clean, old_refs = self.verify_no_old_references(str(exam_page[key]), f"exam_page.{key}")
            if not is_clean:
                errors.extend(old_refs)

        return len(errors) == 0, errors

    def verify_application_flow(self, flow: Dict) -> tuple[bool, List[str]]:
        """Verify application flow uses correct credential references"""
        errors = []

        flow_steps = flow.get("steps", [])
        if not flow_steps:
            errors.append("Application flow missing steps")
            return False, errors

        for i, step in enumerate(flow_steps):
            step_str = json.dumps(step)
            is_clean, old_refs = self.verify_no_old_references(step_str, f"flow_step_{i}")
            if not is_clean:
                errors.extend(old_refs)

        # Verify credential_type field updated
        if flow.get("credential_type") != self.NEW_CREDENTIAL_SHORT:
            errors.append(f"Flow credential_type mismatch: expected {self.NEW_CREDENTIAL_SHORT}, got {flow.get('credential_type')}")

        return len(errors) == 0, errors

    def verify_database_migration(self, migration_result: Dict) -> tuple[bool, List[str]]:
        """Verify database migration completed successfully"""
        errors = []

        expected_fields = ["rows_updated", "rows_verified", "timestamp", "status"]
        for field in expected_fields:
            if field not in migration_result:
                errors.append(f"Migration missing field: {field}")

        if migration_result.get("status") != "success":
            errors.append(f"Migration status not success: {migration_result.get('status')}")

        if migration_result.get("rows_updated", 0) == 0:
            errors.append("Migration updated no rows - possible failure")

        return len(errors) == 0, errors

    def find_old_references_in_codebase(self, files: Dict[str, str]) -> tuple[Set[str], Dict[str, List[int]]]:
        """Find all files and line numbers containing old credential name"""
        files_with_refs = set()
        line_numbers = {}

        import re
        pattern = re.compile(r'\b' + re.escape(self.OLD_CREDENTIAL_NAME) + r'\b', re.IGNORECASE)

        for filepath, content in files.items():
            lines = content.split('\n')
            matching_lines = []
            for line_num, line in enumerate(lines, 1):
                if pattern.search(line):
                    matching_lines.append(line_num)

            if matching_lines:
                files_with_refs.add(filepath)
                line_numbers[filepath] = matching_lines

        return files_with_refs, line_numbers


